const ctx = $input.first().json;
const baseLabel = (score) => score >= 70 ? 'Chaud' : score >= 45 ? 'À qualifier' : score >= 25 ? 'Veille' : 'Écarté';
const rank = { Chaud: 1, 'À qualifier': 2, Veille: 3, 'Écarté': 4 };
const safeJson = (s) => { try { return typeof s === 'string' ? JSON.parse(s) : (s || []); } catch { return []; } };
const decide = (lead) => {
  const exclusions = lead.exclusion_codes || [];
  let label = baseLabel(Number(lead.score || 0));
  let exportAllowed = (label === 'Chaud' && (lead.confidence || 0) >= 65 && lead.identity_status === 'validated') || (label === 'À qualifier' && (lead.confidence || 0) >= 50 && lead.identity_status === 'validated');
  const exclusionReasons = [];
  if (exclusions.includes('inactive_company')) { label = 'Écarté'; exportAllowed = false; exclusionReasons.push('Entreprise inactive'); }
  if (exclusions.includes('excluded_sector')) { label = 'Écarté'; exportAllowed = false; exclusionReasons.push("Secteur exclu par l'ICP V1"); }
  if (lead.identity_status !== 'validated' || exclusions.includes('identity_not_validated')) { exportAllowed = false; exclusionReasons.push('Identité entreprise non validée'); }
  if ((lead.confidence || 0) < 65 && label === 'Chaud') { label = 'À qualifier'; exportAllowed = false; exclusionReasons.push('Confiance insuffisante pour Chaud'); }
  const positives = safeJson(lead.breakdown_json).filter((r) => (r.points || 0) > 0).sort((a, b) => (b.points || 0) - (a.points || 0)).slice(0, 3).map((r) => r.reason);
  const penalties = [...safeJson(lead.penalties_json).map((p) => p.reason), ...exclusionReasons].filter(Boolean).slice(0, 3);
  return { ...lead, priority_version: ctx.priority_version, priority_label: label, priority_export_allowed: exportAllowed, decision_code: `${ctx.priority_version}:${lead.company_key || 'unknown'}:${lead.score_version || 'unknown'}:${lead.score_as_of || ctx.now_utc}`, positive_reasons_json: JSON.stringify(positives), penalty_reasons_json: JSON.stringify(penalties), level_rank: rank[label], priority_decided_at: ctx.now_utc };
};
return (ctx.leads || []).map((json) => ({ json: decide(json) }));
